bool isPrime(int n) {
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

vector<bool> sieve(int n) {
    vector<bool> isP(n + 1, true);
    isP[0] = isP[1] = false;
    for (int i = 2; i * i <= n; i++)
        if (isP[i])
            for (int j = i; j <= n; j += i)
                isP[j] = false;
    return isP;
}

int countDivisors(int n) {
    int c = 0;
    for (int d = 1; d * d <= n; d++)
        if (n % d == 0) c += 2;
    return c;
}
